/* SmartAlarm visual-first interaction prototype. All data/actions are local illustrations. */
(()=>{'use strict';
const S=SMARTALARM.screens,T=SMARTALARM.titles,D=SMARTALARM.labels,$=id=>document.getElementById(id),query=new URLSearchParams(location.search);
let lang=['vi','en','ja'].includes(query.get('lang'))?query.get('lang'):'vi',current=location.hash.slice(1)||'C35',state='ready',forced=null,selection=0,layer='hazard',people=1,confirmedPin=false,navHistory=[],voiceLanguage=null,sosChoice=0,sosLocation='',sosNote='',modalFocus=null;
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const L=(vi,en,ja)=>lang==='en'?en:lang==='ja'?(ja||en):vi;
const loc=x=>D[x]?.[lang]||window.SA_LOCALE_V2?.[x]?.[lang]||x;
const title=s=>T[s.id]?.[lang]||s.title;
const icon=(n,z=24)=>SAVisual.icon(n,z);
const scene=(kind,o={})=>SAVisual.scene(kind,{lang,state,layer,...o});
const find=id=>S.find(x=>x.id===id);
const labels={ready:['Bình thường','Ready','通常'],loading:['Đang tải','Loading','読み込み中'],empty:['Chưa có dữ liệu','No data','データなし'],error:['Lỗi kết nối','Connection error','接続エラー'],offline:['Ngoại tuyến','Offline','オフライン'],denied:['Không có quyền','Access denied','アクセス拒否'],stale:['Dữ liệu cũ','Stale evidence','古い情報'],blocked:['Không xác minh được tuyến','No verified route','経路未確認']};
const groupLabels={'Command':['Điều hành','Command','指令'],'Citizen':['Cá nhân','Personal safety','個人の安全'],'Responder':['Cứu hộ hiện trường','Field response','現場対応'],'Care profiles':['Hồ sơ hỗ trợ','Assistance profiles','支援プロフィール'],'Public address':['Loa và hướng dẫn','Public address','構内放送'],'PhysicalSystems':['Hệ thống vật lý','Physical protection','物理的保護']};
const group=g=>groupLabels[g]?L(...groupLabels[g]):loc(g);
const badge=(text,tone='',ic='')=>`<span class="badge ${tone}">${ic?icon(ic,15):''}${e(text)}</span>`;
const fields=s=>`<dl class="fields">${s.fields.map(([k,v])=>`<div><dt>${e(loc(k))}</dt><dd>${e(loc(v))}</dd></div>`).join('')}</dl>`;
const more=s=>`<details class="disclosure"><summary>${L('Chi tiết và nguồn dữ liệu','Details and sources','詳細と情報源')}</summary>${fields(s)}</details>`;
const fig=(kind,o={},caption='')=>`<div class="scene">${scene(kind,o)}${caption?`<div class="scene-caption">${caption}</div>`:''}</div>`;
const button=(id,text,ic='arrow',cls='primary',extra='')=>`<button type="button" class="${cls}" data-go="${id}" ${extra}>${icon(ic,22)}<span>${e(text)}</span></button>`;
const demoButton=(key,text,ic='check',cls='secondary')=>`<button type="button" class="${cls}" data-demo="${key}">${icon(ic,22)}<span>${e(text)}</span></button>`;
const actionCopy=s=>{
 const a=s.action.toLowerCase();
 if(/save/.test(a))return L('Lưu bản nháp','Save draft','下書きを保存');
 if(/approve/.test(a))return L('Xem bước phê duyệt','Review approval step','承認手順を確認');
 if(/sign in/.test(a))return L('Đăng nhập mẫu','Preview sign-in','ログイン例');
 if(/verify/.test(a))return L('Kiểm tra thông tin','Verify details','情報を確認');
 if(/create/.test(a))return L('Tạo bản nháp','Create draft','下書きを作成');
 if(/submit/.test(a))return L('Kiểm tra và tiếp tục','Review and continue','確認して続行');
 if(/return|back/.test(a))return L('Quay lại','Go back','戻る');
 return L('Mở: ','Open: ','開く：')+title(find(s.next)||s);
};
const action=s=>`<div class="actions">${button(s.next,actionCopy(s),'arrow','primary','data-primary="true"')}</div>`;
const note=(text,tone='')=>`<div class="alert-strip ${tone}">${icon(tone==='blue'?'location':'warning',23)}<p>${text}</p></div>`;
const head=(text,sub='',ic='fire',tone='')=>`<div class="urgent-head"><div class="hazard-mark ${tone}">${icon(ic,40)}</div><div><h1>${text}</h1>${sub?`<p>${sub}</p>`:''}</div></div>`;
const voice=()=>`<div class="voice-bar"><button class="voice-main" data-demo="voice">${icon('voice',25)}${L('Nghe hướng dẫn mẫu','Hear sample guidance','案内音声の例')}</button><button data-demo="stopVoice" aria-label="${L('Dừng âm thanh','Stop audio','音声を停止')}">${icon('close',22)}</button></div><p class="accessibility-note">${L('Có bản chữ · chỉ phát khi bạn chọn nghe.','Text alternative available · plays only on request.','テキストあり・選択した時のみ再生。')}</p>`;
const steps=(names,active=2)=>`<div class="tracking">${names.map((n,i)=>`<div class="track-node ${i<active?'done':i===active?'current':''}"><span>${icon(i<active?'check':i===active?'team':'clock',20)}</span>${n}</div>`).join('')}</div>`;
const timeline=s=>`<div class="timeline">${s.fields.map(([k,v])=>`<div><strong>${e(loc(k))}</strong><p>${e(loc(v))}</p></div>`).join('')}</div>`;
const editable=(s,skip=[])=>`<form class="visual-form" id="screenform">${s.fields.filter(([k])=>!skip.includes(k)).map(([k,v],i)=>`<label>${e(loc(k))}<${v.length>70?'textarea':'input'} id="field-${i}" ${v.length>70?'rows="2"':`value="${e(v)}" type="${/email/i.test(k)?'email':'text'}"`} required aria-label="${e(loc(k))}">${v.length>70?e(v)+'</textarea>':''}</label>`).join('')}</form>`;
const list=(s,ic='person')=>`<div class="evidence-list">${s.fields.map(([k,v])=>`<div class="evidence-row"><span class="evidence-icon">${icon(ic,27)}</span><div><strong>${e(loc(k))}</strong><p>${e(loc(v))}</p></div>${icon('arrow',18)}</div>`).join('')}</div>`;
function phone(s){let h='';
 if(s.id==='C01')h=`${head(L('Có cháy tại tòa A','Fire in Building A','A棟で火災'),L('Tòa A · Tầng 05','Building A · Floor 05','A棟・5階'),'fire')}${fig('campus',{showRoute:false})}<div class="actions">${button('C02',L('Xem việc cần làm','What should I do?','取るべき行動'),'exit')}${button('C05',L('Tôi cần cứu hộ','I need rescue','救助が必要'),'SOS','secondary')}</div><div class="response-summary"><div>${icon('person',26)}<strong>3</strong><small>${L('Đã tự báo an toàn','Reported safe','安全と自己申告')}</small></div><div>${icon('warning',26)}<strong>1</strong><small>${L('Chưa có thông tin','No recent report','情報なし')}</small></div><div>${icon('team',26)}<strong>${L('Gia đình','Family','家族')}</strong><small><button class="quiet" data-go="C22">${L('Xem','View','表示')}</button></small></div></div>${more(s)}`;
 else if(s.id==='C02')h=`${head(L('Có cháy tại tòa A','Fire in Building A','A棟で火災'),L('Nguồn: Điều hành công trình','Source: site command','情報源：施設指令'),'fire')}${fig('evacuation',{showRoute:false})}<div class="landmark">${icon('exit',35)}<div><strong>${L('Xem hướng dẫn của công trình','Use the site guidance','施設の案内を確認')}</strong><small>${L('Không tự suy đoán đường thoát','Do not assume a route is clear','経路の安全を推測しない')}</small></div></div><div class="actions">${button('C03',L('Mở sơ đồ thoát hiểm','Open evacuation plan','避難図を開く'),'building')}${button('C05',L('Tôi không tự di chuyển được','I cannot move without help','自力で移動できない'),'accessible','secondary')}</div>${more(s)}`;
 else if(['C03','C35','C36','C37','C38','C39'].includes(s.id))h=guidance(s);
 else if(s.id==='C05'){const names=[L('Cháy / mắc kẹt','Fire / trapped','火災・閉じ込め'),L('Té ngã / sức khỏe','Fall / medical help','転倒・医療支援'),L('Tai nạn giao thông','Road collision','交通事故'),L('Nguy cơ cá nhân','Personal threat','身の危険'),L('Trợ giúp khác','Other assistance','その他の支援')];h=`<h1>${L('Bạn cần giúp gì?','What help do you need?','どんな支援が必要ですか？')}</h1><div class="sos-grid">${names.map((n,i)=>`<button class="sos-choice ${selection===i?'selected':''}" data-select="${i}" aria-pressed="${selection===i}">${icon(['fire','fall','collision','shield','SOS'][i],44)}<span>${n}</span>${selection===i?icon('check',18):''}</button>`).join('')}</div><div class="actions">${button('C06',L('Chọn vị trí cần giúp','Set rescue location','救助場所を指定'),'location')}</div>${more(s)}`;}
 else if(s.id==='C06')h=`<h1>${L('Cứu hộ tìm bạn ở đâu?','Where can we find you?','救助場所はどこですか？')}</h1>${fig('floor',{showRoute:false})}<div class="map-pin-action">${demoButton('confirmPin',confirmedPin?L('Đã xác nhận vị trí mẫu','Example location confirmed','例の位置を確認済み'):L('Xác nhận Tầng 05 · Phòng 505','Confirm Floor 05 · Room 505','5階・505号室を確認'),'location','primary blue')}</div><form class="visual-form" id="screenform"><label>${L('Vị trí bạn cung cấp','Your reported location','申告する位置')}<input id="sosLocation" value="${sosLocation?e(sosLocation):L('Tòa A / Tầng 05 / Phòng 505','Building A / Floor 05 / Room 505','A棟 / 5階 / 505号室')}" required></label><label>${L('Số người cần hỗ trợ','People needing help','支援が必要な人数')}</label><div class="stepper"><button type="button" data-demo="minusPeople" aria-label="${L('Giảm số người','Fewer people','人数を減らす')}">−</button><output id="people">${people}</output><button type="button" data-demo="plusPeople" aria-label="${L('Tăng số người','More people','人数を増やす')}">+</button></div><label>${L('Điều cần biết','What should we know?','伝えたいこと')}<textarea id="sosNote" placeholder="${L('Ví dụ: tôi không đi cầu thang được','For example: I need help with stairs','例：階段で支援が必要')}" aria-label="${L('Ghi chú','Note','メモ')}">${e(sosNote)}</textarea></label></form><div class="actions">${button('C07',L('Kiểm tra yêu cầu','Review request','依頼を確認'),'check','primary','data-primary="true"')}</div>${more(s)}`;
 else if(s.id==='C07')h=`${head(L('Kiểm tra trước khi gửi','Review before sending','送信前に確認'),L('Gửi đến điều hành công trình','To site command','施設指令へ'),'SOS')}${fig('rescue',{showRoute:false})}<div class="response-summary"><div>${icon(['fire','fall','collision','shield','SOS'][sosChoice],30)}<strong>${[L('Cháy','Fire','火災'),L('Té ngã / sức khỏe','Fall / medical help','転倒・医療支援'),L('Tai nạn','Collision','事故'),L('Nguy hiểm cá nhân','Personal danger','身の危険'),L('SOS khác','Other SOS','その他SOS')][sosChoice]}</strong></div><div>${icon('location',30)}<strong>${e(sosLocation||L('Tầng 05 / Phòng 505','Floor 05 / Room 505','5階 / 505号室'))}</strong><small>${L('Vị trí tự báo','Reported location','申告位置')}</small></div><div>${icon('person',30)}<strong>${people}</strong><small>${L('người','people','人')}</small></div></div>${sosNote?`<div class="sheet">${e(sosNote)}</div>`:''}${note(L('Vị trí và ghi chú chỉ chia sẻ với đội xử lý yêu cầu.','Location and notes are shared with the assigned response team.','位置とメモは担当チームに共有します。'),'blue')}<div class="actions">${button('C08',L('Gửi SOS trong bản mẫu','Send sample SOS','サンプルSOSを送信'),'SOS','primary','data-primary="true"')}${button('C06',L('Sửa vị trí','Edit location','位置を修正'),'location','secondary')}</div>${more(s)}`;
 else if(s.id==='C08')h=`<div class="statusline">${badge('SOS-041','red','SOS')}${badge(L('Chờ liên lạc','Awaiting contact','連絡待ち'),'blue','team')}</div><h1>${L('Đội cứu hộ đã được phân công','A team has been assigned','担当チームを割り当て済み')}</h1>${fig('rescue',{showRoute:false})}${steps([L('Đã nhận','Received','受信'),L('Đã xác nhận','Acknowledged','確認'),L('Phân công','Assigned','割当'),L('Tiếp cận','Contact','接触')],2)}<div class="contact-card"><span class="person-icon">${icon('team',30)}</span><div class="person-copy"><strong>Rescue 02</strong><p>${L('Chưa có thời gian đến được xác nhận','No confirmed arrival time','到着時刻は未確認')}</p></div>${icon('radio',30)}</div><div class="actions">${button('C09',L('Nhắn đội cứu hộ','Message the team','チームへ連絡'),'radio')}${button('C10',L('Cập nhật tình trạng','Update my situation','状況を更新'),'person','secondary')}</div>${more(s)}`;
 else if(['C09','C20'].includes(s.id))h=chat(s);
 else if(s.id==='C11')h=`<h1>${L('Bạn đang ở tình trạng nào?','What is your status?','現在の状況は？')}</h1>${fig('rescue',{showRoute:false})}${[L('Tôi đã tới điểm tập kết','I reached the assembly point','集合場所に到着'),L('Tôi vẫn cần hỗ trợ','I still need assistance','まだ支援が必要')].map((x,i)=>`<button class="care-choice ${selection===i?'selected':''}" data-select="${i}" aria-pressed="${selection===i}">${icon(i?'SOS':'check',32)}<span><strong>${x}</strong><small>${i?L('Mở yêu cầu cứu hộ','Open rescue request','救助依頼を開く'):L('Trạng thái do tôi tự xác nhận','This is my own report','本人による申告')}</small></span></button>`).join('')}<div class="actions">${button(selection?'C05':'C12',selection?L('Tôi cần giúp','I need help','支援が必要'):L('Xác nhận tình trạng của tôi','Confirm my status','状況を確認'),selection?'SOS':'check',selection?'primary':'primary green')}</div>${more(s)}`;
 else if(s.id==='C12')h=`<div class="self-report">${icon('check',44)}<div><strong>${L('Đã tự báo an toàn','Self-reported safe','安全と自己申告済み')}</strong><small>${L('Sự cố vẫn đang hoạt động','The incident remains active','事案は継続中')}</small></div></div><div style="margin:18px 0">${fig('identity',{showRoute:false})}</div>${steps([L('Đã lưu','Saved','保存'),L('Chờ gửi','Queued','送信待ち'),L('Đã nhận?','Received?','受信？')],1)}${note(L('Đã lưu không có nghĩa mọi người đã nhận. Xem kết quả gửi bên dưới.','Saved does not mean everyone received it. Check delivery details.','保存済みは全員の受信を意味しません。配信状況を確認してください。'),'blue')}<div class="actions">${button('C13',L('Xem kết quả thông báo','View delivery details','配信状況を表示'),'phone','primary green')}</div>${more(s)}`;
 else if(['C14','C15','C16','C17','C39'].includes(s.id))h=disaster(s);
 else if(['C19','C22','C31'].includes(s.id))h=`<h1>${e(title(s))}</h1><div class="avatar-group">${['person','person','person','warning'].map(n=>`<span>${icon(n,26)}</span>`).join('')}</div>${list(s,'person')}${s.id==='C22'?note(L('Chưa có báo cáo không đồng nghĩa gặp nạn hoặc đã an toàn.','No report does not establish danger or safety.','報告なしから危険や安全を判断しません。')):''}${action(s)}${more(s)}`;
 else if(s.id==='C25')h=`${head(L('Bạn có cần giúp không?','Do you need help?','支援が必要ですか？'),L('Thiết bị ghi nhận có thể té ngã','Possible fall from wearable','ウェアラブルが転倒の可能性を検出'),'fall','amber')}${fig('care',{showRoute:false})}<div class="critical-counter"><div class="counter-ring" aria-label="${L('30 giây minh họa, không chạy đếm','30 second illustration, not counting down','30秒の例・カウントダウンなし')}">30</div><p>${L('Nếu không phản hồi, chính sách sẽ báo đội chăm sóc.','No response triggers the configured care escalation.','応答がなければ設定された支援連絡へ。')}</p></div><div class="actions two">${button('C01',L('Tôi ổn','I am OK','大丈夫'),'check','secondary')}${button('C08',L('Cần giúp ngay','Help now','今すぐ支援'),'SOS')}</div><p class="critical-label">${L('Tình huống mẫu · không chạy đếm hoặc tự gọi cứu hộ.','Illustrative state · no countdown or automatic dispatch.','サンプル状態・自動カウントや出動なし。')}</p>${more(s)}`;
 else if(s.id==='C27')h=`<div class="quiet-escape">${button('C01',L('Thoát nhanh','Quick exit','すぐ閉じる'),'close','secondary')}</div><h1>${L('Liên hệ riêng','Private contact','非公開の連絡')}</h1>${fig('identity',{showRoute:false})}<div class="self-report" style="background:#edf3f6;color:#294f63">${icon('lock',35)}<div><strong>${L('Không âm thanh, không rung','No sound. No vibration.','音・振動なし')}</strong><small>${L('Chỉ người xử lý được xem','Assigned operator only','担当者のみ閲覧')}</small></div></div><div class="actions">${button('C08',L('Gửi yêu cầu riêng trong bản mẫu','Send private sample request','非公開サンプル依頼を送信'),'lock','primary blue')}</div>${more(s)}`;
 else if(s.type==='form'){const kind=['C24'].includes(s.id)?'care':['C26'].includes(s.id)?'campus':['C04','C34','C40'].includes(s.id)?'coverage':'identity';h=`<h1>${e(title(s))}</h1>${fig(kind,{showRoute:false})}<div style="margin-top:18px">${editable(s)}</div>${['C04','C40'].includes(s.id)?voice():''}${action(s)}${more(s)}`;}
 else h=`<h1>${e(title(s))}</h1>${fig(s.id==='C18'?'floor':s.id==='C30'?'identity':'campus',{showRoute:false,state:s.id==='C18'?'stale':state})}${list(s,s.id==='C18'?'cloud':'phone')}${action(s)}${more(s)}`;
 return h.replace('Incendie?',L('Có cháy tại tòa A','Fire in Building A','A棟で火災'));
}
function guidance(s){const unknown=s.id==='C38',withdrawn=s.id==='C37',staticPlan=s.id==='C03',landmark=s.id==='C36',outdoor=s.id==='C39';
 if(unknown||withdrawn)return `${head(unknown?L('Chưa xác định được đường đi','No verified route','確認済み経路なし'):L('Dừng dùng tuyến cũ','Previous route withdrawn','旧経路は取り消し'),unknown?L('Tầng và hướng chưa được xác nhận','Floor and heading are unconfirmed','階と向きが未確認'):L('Có báo cáo nguy hiểm mới','New hazard report','新たな危険情報'),'warning','amber')}<div class="route-suppressed">${fig('floor',{state:'blocked',showRoute:false},L('Ẩn chỉ dẫn hướng khi chưa đủ bằng chứng','Directional guidance is hidden without reliable evidence','信頼できる情報がないため方向案内を非表示'))}</div><div class="next-action uncertain"><span class="large-icon">${icon(unknown?'location':'close',58)}</span><div><strong>${unknown?L('Tìm mã vị trí hoặc nhờ hỗ trợ','Find a location marker or ask for help','位置マーカーを確認・支援を依頼'):L('Xem tuyến mới đã được rà soát','Review the updated route','更新経路を確認')}</strong></div></div><div class="actions">${button(unknown?'C05':'C35',unknown?L('Tôi cần người hướng dẫn','I need assistance','支援が必要'):L('Mở hướng dẫn mới','Open updated guidance','新しい案内を開く'),unknown?'SOS':'building')}${unknown?button('C06',L('Cung cấp vị trí của tôi','Share my reported location','位置を申告'),'location','secondary'):''}</div>${voice()}${more(s)}`;
 const top=staticPlan?L('Sơ đồ đã được phê duyệt','Published evacuation plan','承認された避難図'):landmark?L('Nhìn mốc, không đoán hướng','Use the landmark, not a guess','向きを推測せず目印を確認'):outdoor?L('Hướng ra ngoài vùng ảnh hưởng','Away from the affected area','影響範囲の外へ'):L('Đến cầu thang Tây','Find the West stair','西階段を確認');
 return `<div class="statusline">${badge(staticPlan?L('Tuyến chưa xác minh','Route unverified','経路未確認'):L('Hướng dẫn v18','Guidance v18','案内 v18'),staticPlan?'amber':'green',staticPlan?'warning':'check')}${badge('A / 05','blue','building')}</div><h1>${top}</h1>${staticPlan?note(L('Sơ đồ lưu không chứng minh lối đi hiện tại còn an toàn.','A stored plan does not establish that a path is currently clear.','保存された図は現在の通行可能性を保証しません。')):''}${fig(landmark?'evacuation':outdoor?'campus':'floor',{showRoute:!staticPlan,state:staticPlan?'stale':'ready'},landmark?L('Hướng thiết bị không đáng tin · dùng biển làm mốc','Heading unreliable · use the sign as a landmark','端末の向きは不確実・標識を目印に'):L('Sơ đồ mẫu · địa điểm minh họa','Sample plan · illustrative location','参考図・仮の場所'))}<div class="landmark">${icon(staticPlan?'building':'stairs',36)}<div><strong>${staticPlan?L('Tòa A · Sơ đồ v12','Building A · Plan v12','A棟・図面v12'):L('Biển “Cầu thang Tây”','“West stair” sign','「西階段」の標識')}</strong><small>${staticPlan?L('Đối chiếu chỉ dẫn tại công trình','Follow the approved site instructions','現地の承認済み案内を確認'):L('Không đi vào hành lang có khói trong sơ đồ','Avoid the illustrated smoke corridor','図の煙のある廊下を避ける')}</small></div></div>${voice()}<div class="actions">${button(staticPlan?'C05':landmark?'C36':'C36',staticPlan?L('Tôi cần hỗ trợ di chuyển','I need mobility assistance','移動支援が必要'):landmark?L('Nghe lại mốc hướng dẫn','Repeat the landmark cue','目印案内を再生'):L('Xem mốc tiếp theo','Show the next landmark','次の目印を表示'),staticPlan?'accessible':landmark?'voice':'exit',staticPlan?'primary':'primary green',landmark?'data-repeat="true"':'')}${button('C38',L('Tôi không nhận ra vị trí','I cannot identify my location','現在地が分からない'),'location','secondary')}</div>${more(s)}`;
}
function disaster(s){const shelter=['C16','C17'].includes(s.id);return `${head(shelter?L('Điểm hỗ trợ được chỉ định','Designated assistance points','指定支援場所'):L('Theo dõi vùng ngập','Flood watch area','洪水警戒区域'),L('Nguồn và thời hạn phải còn hiệu lực','Check source and validity','情報源と有効期限を確認'),shelter?'building':'flood','amber')}${fig('campus',{showRoute:false,hazard:'flood'})}${shelter?`<div class="landmark">${icon('accessible',32)}<div><strong>North shelter</strong><small>${L('Lối vào không bậc · theo báo cáo hiện có','Step-free entrance · reported information','段差なし入口・報告情報')}</small></div></div>`:note(L('Vùng tô màu là vùng cảnh báo; không phải bản đồ độ sâu ngập.','The shaded area is an advisory zone, not a flood-depth map.','色付き部分は警戒区域であり浸水深ではありません。'))}${list(s,shelter?'building':'flood')}${action(s)}${more(s)}`;}
function chat(s){return `<h1>${e(title(s))}</h1><div class="contact-card"><span class="person-icon">${icon(s.id==='C20'?'person':'team',30)}</span><div><strong>${s.id==='C20'?L('Gia đình','Family','家族'):'Rescue 02'}</strong><p>${L('Tin nhắn trong bản mẫu','Prototype conversation','サンプル会話')}</p></div></div><div class="conversation">${s.fields.map(([k,v],i)=>`<div class="bubble ${i===1?'me':''}"><small>${e(loc(k))}</small>${e(loc(v))}</div>`).join('')}<div id="messages"></div></div><div class="rowlinks">${['location','accessible','warning'].map((ic,i)=>demoButton('quick'+i,[L('Vị trí của tôi','My location','現在地'),L('Cần hỗ trợ di chuyển','Mobility help','移動支援'),L('Tình trạng thay đổi','Situation changed','状況変化')][i],ic,'quiet')).join('')}</div><div class="composer"><input id="message" aria-label="${L('Nội dung tin nhắn','Message text','メッセージ')}" placeholder="${L('Nhập tin nhắn mẫu…','Type a sample message…','サンプルメッセージ…')}"><button data-demo="sendMessage" aria-label="${L('Gửi tin mẫu','Send sample message','サンプル送信')}">${icon('arrow',24)}</button></div>${s.id==='C20'?action(s):''}${more(s)}`;}
function responder(s){if(s.type==='chat')return chat(s);let sceneKind=['R04'].includes(s.id)?'campus':['R05','R10'].includes(s.id)?'floor':['R06','R07','R08'].includes(s.id)?'care':'rescue';
 const warning=s.id==='R12'||s.id==='R11';return `<div class="statusline">${badge('Rescue 02','blue','team')}${badge(s.id==='R01'?L('Sẵn sàng','Available','対応可能'):'INC-2041',warning?'amber':'','radio')}</div><h1>${e(title(s))}</h1>${warning?note(s.id==='R12'?L('Nhiệm vụ đã đổi chủ. Giữ ghi nhận, không ghi đè trạng thái mới.','Task ownership changed. Preserve your note; do not overwrite the newer state.','担当が変更。記録を保持し新状態を上書きしない。'):L('Chưa gửi lên máy chủ. Bản ghi vẫn ở thiết bị.','Not sent to the server. Records remain on this device.','サーバー未送信。記録は端末に保持。')):''}${fig(sceneKind,{showRoute:s.id==='R04',state:warning?'offline':'ready'})}${s.id==='R03'?`<div class="landmark">${icon('accessible',34)}<div><strong>${L('Hỗ trợ tại phòng 505','Assist at Room 505','505号室で支援')}</strong><small>${L('Vị trí tự báo · khói chưa xác nhận','Reported location · smoke unconfirmed','申告位置・煙は未確認')}</small></div></div><div class="actions two">${button('R04',L('Nhận nhiệm vụ','Accept task','任務を受ける'),'check','primary blue')}${demoButton('declineTask',L('Không thể nhận','Cannot accept','受けられない'),'close')}</div>`:s.type==='form'?`<div style="margin-top:18px">${editable(s)}</div>${action(s)}`:`${list(s,s.id==='R11'?'cloud':'radio')}${action(s)}`}${s.id==='R08'?note(L('Đã hỗ trợ người này; không tự đóng toàn bộ sự cố.','This person was assisted; the incident is not automatically closed.','この人への支援完了で事案全体を自動終結しません。'),'blue'):''}${more(s)}`;}
function care(s){const ops=['H07','H08','H09','H10','H11'].includes(s.id);if(ops){return `<div class="product-head"><div><h1>${e(title(s))}</h1><span class="badge amber">${L('Không cần chờ SOS','Do not wait for SOS','SOSを待たない')}</span></div></div><div class="split"><div>${fig(s.id==='H10'?'floor':'care',{showRoute:false})}${s.id==='H09'?`<div class="response-summary"><div>${icon('location',28)}<strong>${L('Phơi nhiễm','Exposure','影響')}</strong><small>QR · 2 min</small></div><div>${icon('accessible',28)}<strong>${L('Cần hỗ trợ','Assistance','支援')}</strong><small>${L('Hồ sơ hỗ trợ','Functional profile','支援記録')}</small></div><div>${icon('SOS',28)}<strong>0 SOS</strong><small>${L('Vẫn cần kiểm tra','Check still needed','確認が必要')}</small></div></div>`:''}</div><section class="sheet white"><h2>${L('Bằng chứng và quyết định','Evidence and decision','証拠と判断')}</h2>${fields(s)}${s.id==='H11'?note(L('Nội dung y tế bị hạn chế. Chỉ hiển thị phạm vi được cấp quyền.','Medical content is restricted to the authorized scope.','医療情報は許可された範囲に限定。'),'blue'):note(L('Ưu tiên cần người có thẩm quyền kiểm tra. Không suy luận an toàn từ việc không có SOS.','An authorized person reviews priority. No SOS does not establish safety.','優先度は権限者が確認。SOSなしは安全を意味しません。'))}${action(s)}</section></div>`;}
 return `<h1>${e(title(s))}</h1>${fig(s.id==='H02'||s.id==='H04'?'identity':'care',{showRoute:false})}${s.id==='H01'?`<div class="landmark">${icon('accessible',35)}<div><strong>${L('Nhu cầu hỗ trợ trước, chẩn đoán sau','Support needs before medical detail','まず支援ニーズを確認')}</strong><small>${L('Tôi cần người giúp khi đi cầu thang','I need help using stairs','階段で支援が必要')}</small></div></div>`:''}<div style="margin-top:18px">${s.type==='form'?editable(s):list(s,'person')}</div>${action(s)}${more(s)}`;
}
function command(s){const main=['O01','O02','O04','O24','O35'].includes(s.id);const tabs=`<div class="command-tools">${[['hazard','fire',L('Nguy cơ','Hazards','危険')],['people','person',L('Con người','People','人')],['equipment','pump',L('Thiết bị','Equipment','設備')]].map(([v,ic,n])=>`<button data-layer="${v}" class="${layer===v?'active':''}" aria-pressed="${layer===v}">${icon(ic,19)}${n}</button>`).join('')}</div>`;
 const urgent=[['12',L('Sự cố đang mở','Active incidents','対応中の事案'),'fire'],['2',L('P1 chưa xác nhận','Unacknowledged P1','未確認P1'),'warning'],['7',L('SOS đang mở','Open SOS','未完了SOS'),'SOS'],['18',L('Đội sẵn sàng','Available units','対応可能チーム'),'team']];
 const rail=layer==='equipment'?`<h2>${L('Hệ thống bảo vệ','Protection systems','保護設備')}</h2><div class="priority-person"><strong>${L('Bơm · van · waterflow','Pump · valve · waterflow','ポンプ・弁・水流')}</strong><p>${L('Xem phản hồi tại tủ cục bộ','Review local-controller feedback','現地制御盤の応答を確認')}</p>${button('F08',L('Mở sơ đồ hệ nước','Open water-system view','給水系統図を開く'),'pump','secondary')}</div><div class="priority-person"><strong>PA · A05</strong><p>${L('7 đang phát / 1 chưa rõ','7 playing / 1 unknown','7再生中 / 1不明')}</p>${button('P04',L('Xem trạng thái loa','Inspect playback','放送状態を確認'),'voice','secondary')}</div>`:layer==='people'?`<h2>${L('Cần người tiếp cận','People needing contact','接触が必要な人')}</h2>${[['Alex','505',L('Cần hỗ trợ di chuyển · chưa SOS','Mobility support · no SOS','移動支援・SOSなし')],['Morgan','?',L('Vị trí cũ · cần xác minh','Stale position · verify','古い位置・要確認')]].map(([n,room,why])=>`<div class="priority-person"><strong>${icon('accessible',19)} ${n} · ${room}</strong><p>${why}</p>${button('H09',L('Kiểm tra bằng chứng','Review evidence','証拠を確認'),'person','secondary')}</div>`).join('')}`:`<h2>${L('Ưu tiên tiếp theo','Next priorities','次の優先事項')}</h2><div class="priority-person"><strong>${icon('fire',19)} A05 · P1</strong><p>${L('Khói hành lang Đông · cần kiểm tra tuyến','East corridor smoke · review routes','東廊下の煙・経路確認')}</p>${button('O35',L('Xem vùng hạn chế','Review restrictions','制限区域を確認'),'location','secondary')}</div><div class="priority-person"><strong>${icon('person',19)} 3 ${L('chưa rõ','unconfirmed','未確認')}</strong><p>${L('Không coi vắng tín hiệu là an toàn','No signal does not mean safe','信号なしは安全ではない')}</p>${button('H08',L('Mở cứu hộ chủ động','Open proactive rescue','先行救助を開く'),'team','secondary')}</div>`;
 if(main)return `<div class="command-heading"><div><h1>${s.id==='O04'?L('Cháy · Tòa A / Tầng 05','Fire · Building A / Floor 05','火災・A棟 / 5階'):e(title(s))}</h1><p>${L('Tình huống minh họa 10:42 · không phải dữ liệu trực tiếp','Scenario at10:42 · not live data','10:42の想定場面・ライブ情報ではありません')}</p></div>${tabs}</div>${s.id==='O24'?note(L('DIỄN TẬP · bộ chấp hành và người nhận thật được tách riêng','EXERCISE · live actuators and recipients are isolated','訓練・実機と実際の受信者は分離'),'blue'):''}<div class="command-stats">${urgent.map(([n,label,ic])=>`<div class="command-stat">${icon(ic,27)}<div><b>${n}</b><span>${label}</span></div></div>`).join('')}</div><div class="command-canvas"><div>${fig(layer==='equipment'?'firewater':s.id==='O01'||s.id==='O02'?'campus':'floor',{dark:true,showRoute:s.id!=='O35',layer})}</div><aside class="command-rail">${rail}</aside></div><div class="command-bottom"><section class="sheet white"><h2>${L('Bằng chứng cần đối chiếu','Evidence to reconcile','照合する証拠')}</h2>${list(s,layer==='people'?'person':'radio')}</section><section class="sheet white"><h2>${L('Thao tác tiếp theo','Next actions','次の操作')}</h2><div class="rowlinks">${button('O08',L('Điều phối đội','Dispatch teams','チーム割当'),'team','secondary')}${button('P01',L('Phủ loa cảnh báo','Speaker coverage','放送範囲'),'voice','secondary')}${button('O36',L('Đồng bộ chỉ dẫn','Guidance receipts','案内の受信'),'phone','secondary')}</div>${action(s)}</section></div>${more(s)}`;
 if(['O03','O05','O07'].includes(s.id))return `<div class="product-head"><h1>${e(title(s))}</h1>${badge(L('Chưa đủ để tự kết luận','Human verification needed','人による確認が必要'),'amber','warning')}</div><div class="split"><div class="photo-evidence">${fig('floor',{showRoute:false})}<div class="bounding-box"><span>${L('Khói? · chưa xác minh','Smoke? · unverified','煙？・未確認')}</span></div><div class="video-label">CAM-A05-03 · ${L('Minh họa','Illustration','例')}</div></div><section class="sheet white"><h2>${L('Đối chiếu nguồn','Compare sources','情報源を比較')}</h2>${fields(s)}${note(L('Gợi ý mô hình không thay thế xác minh của người vận hành.','A model indication does not replace operator verification.','モデルの検出は担当者の確認の代わりになりません。'))}${action(s)}</section></div>`;
 if(['O08','O09'].includes(s.id))return `<h1>${e(title(s))}</h1><div class="split"><div>${fig('campus',{showRoute:false})}<div class="landmark">${icon('accessible',32)}<div><strong>SOS-041 · 05 / 505</strong><small>${L('Cần hỗ trợ di chuyển · vị trí tự báo','Mobility support · reported location','移動支援・申告位置')}</small></div></div></div><div class="sheet white"><h2>${L('Chọn đội phù hợp','Match a capable team','対応可能チームを選択')}</h2><div class="operator-list">${[['Rescue 02',L('Sẵn sàng · cứu hộ cháy','Available · fire rescue','対応可能・火災救助'),'team'],['Medical 01',L('Đang làm nhiệm vụ','Already assigned','任務中'),'heart'],['Security 03',L('Sẵn sàng · vành đai','Available · perimeter','対応可能・警戒'),'shield']].map(([n,st,ic],i)=>`<button class="care-choice ${selection===i?'selected':''}" data-select="${i}">${icon(ic,32)}<span><strong>${n}</strong><small>${st}</small></span>${selection===i?icon('check',20):''}</button>`).join('')}</div>${s.id==='O09'?editable(s):''}${note(L('Việc phân công phải chờ đội chấp nhận; không hiển thị đã đến.','Assignment still requires team acceptance; it does not mean arrival.','割当後もチームの受諾が必要。到着済みではありません。'),'blue')}${action(s)}</div></div>${more(s)}`;
 if(['O11','O12','O34'].includes(s.id))return `<h1>${e(title(s))}</h1><div class="split"><div>${fig('floor',{showRoute:false,layer:'people'})}</div><section class="sheet white"><h2>${L('Trạng thái có nguồn','Source-backed status','情報源付きの状態')}</h2>${list(s,'person')}${note(L('Chưa rõ không đồng nghĩa đã an toàn. Tách vị trí tự báo, có mặt và xác nhận cứu hộ.','Unknown is not safe. Distinguish reported position, presence and assistance confirmation.','不明は安全ではありません。申告位置・在場・支援確認を区別。'))}${action(s)}</section></div>`;
 if(['O13','O14','O15','O16','O17','O36'].includes(s.id))return warningWorkspace(s);
 if(['O18','O19'].includes(s.id))return `<h1>${e(title(s))}</h1>${note(L('Giám sát và xem xét trong bản mẫu; không gửi lệnh tới thiết bị.','Review-only prototype; no equipment command is sent.','確認専用のプロトタイプ。機器への命令なし。'))}<div class="split">${fig('coverage',{showRoute:false})}<section class="sheet white">${fields(s)}${steps([L('Đề nghị','Requested','要求'),L('Duyệt','Approved','承認'),L('Đã nhận','Accepted','受信'),L('Phản hồi','Feedback','応答')],2)}${badge(L('Chưa xác nhận hoàn tất','Completion unconfirmed','完了未確認'),'amber','warning')}<div class="actions">${button('P04',L('Xem phản hồi phát loa','Inspect playback evidence','再生の証拠を確認'),'voice','secondary')}</div></section></div>`;
 const kind=['O26','O27','O28','O29'].includes(s.id)?'campus':['O21','O22'].includes(s.id)?'analytics':['O33','O25'].includes(s.id)?'topology':'rescue';
 return `<h1>${e(title(s))}</h1><div class="split">${fig(kind,{showRoute:false})}<section class="sheet white">${s.type==='form'?editable(s):s.type==='timeline'?timeline(s):list(s,'radio')}${action(s)}</section></div>${more(s)}`;
}
function warningWorkspace(s){return `<h1>${e(title(s))}</h1><div class="split"><div>${fig('coverage',{showRoute:false})}<div class="response-summary"><div>${icon('phone',28)}<strong>312</strong><small>${L('App cập nhật','App updated','アプリ更新')}</small></div><div>${icon('voice',28)}<strong>7 / 8</strong><small>${L('Loa báo đang phát','Reported playing','再生報告')}</small></div><div>${icon('warning',28)}<strong>28</strong><small>${L('Chưa rõ','Unknown','不明')}</small></div></div></div><section class="sheet white"><h2>${L('Thông điệp và người nhận','Message and audience','メッセージと対象')}</h2><div class="landmark">${icon('exit',30)}<div><strong>${L('Dùng hướng dẫn đã được phê duyệt','Use approved site guidance','承認済みの案内を確認')}</strong><small>v18 · A05</small></div></div>${s.type==='form'?editable(s):fields(s)}${note(L('Bản dịch chưa duyệt không được phát tự động. Gửi không đồng nghĩa đã đọc hoặc đã nghe.','Unapproved translations are not released automatically. Sent does not mean read or heard.','未承認の翻訳は自動配信しません。送信は読了・聴取を意味しません。'))}${action(s)}</section></div>`;}
function pa(s){const live=s.id==='P06';return `<div class="product-head"><h1>${e(title(s))}</h1>${badge('PA · INC-2041','blue','voice')}</div><div class="split"><div>${fig(s.id==='P07'?'drone':'coverage',{showRoute:false})}${live?`<div class="audio-meter">${icon('radio',45)}<strong>${L('Microphone chưa bật','Microphone inactive','マイク未作動')}</strong></div>`:`<div class="speaker-sequence">${['VI','EN','JA'].map((v,i)=>`<button class="${(voiceLanguage||lang)===['vi','en','ja'][i]?'selected':''}" data-voice-lang="${['vi','en','ja'][i]}">${icon('voice',18)} ${v}</button>`).join('')}</div>`}<div class="wave" role="img" aria-label="${L('Dạng sóng minh họa, không phải âm thanh trực tiếp','Illustrative waveform, not live audio','波形の例・ライブ音声ではありません')}">${Array.from({length:30},(_,i)=>`<i style="height:${12+(i*13%59)}px"></i>`).join('')}</div>${live?demoButton('mic',L('Xem quyền microphone','Review microphone permission','マイク権限を確認'),'lock'):voice()}</div><section class="sheet white"><h2>${L('Vùng phát và phản hồi','Zones and feedback','放送範囲と応答')}</h2>${s.type==='form'&&!['P07','P09'].includes(s.id)?editable(s):fields(s)}${note(L('Tủ khẩn cấp tại chỗ có quyền ưu tiên. Phản hồi thiết bị không chứng minh mọi người đã nghe.','The local emergency controller has priority. Device feedback does not prove everyone heard it.','現地非常制御盤を優先。機器の応答は全員の聴取を証明しません。'))}${action(s)}</section></div>`;}
function stateContent(s){const cfg={loading:['cloud',L('Đang lấy thông tin','Retrieving information','情報を取得中'),L('Chưa có dữ liệu mới để đưa ra chỉ dẫn.','No new information is available for guidance yet.','新しい案内情報はまだありません。')],empty:['search',L('Chưa có bản ghi phù hợp','No matching records','一致する記録なし'),L('Đổi bộ lọc hoặc quay lại danh sách. Không tự coi là đã an toàn.','Change filters or return to the list. Empty results do not establish safety.','条件を変更してください。空の結果は安全を意味しません。')],error:['cloud',L('Chưa kết nối được','Could not connect','接続できません'),L('Chưa xác nhận thao tác đã được nhận. Kiểm tra kết nối rồi thử lại.','Receipt has not been confirmed. Check connectivity before retrying.','受信は未確認です。接続を確認して再試行。')],offline:['cloud',L('Bạn đang ngoại tuyến','You are offline','オフラインです'),L('Chỉ có dữ liệu đã lưu. Yêu cầu chưa được xác nhận gửi; không hiển thị tuyến trực tiếp.','Only cached data is available. Sending is unconfirmed; live routing is hidden.','保存情報のみ。送信未確認・ライブ経路は非表示。')],denied:['lock',L('Cần quyền phù hợp','Permission required','権限が必要です'),L('Không hiển thị dữ liệu ngoài quyền. Quay lại hoặc liên hệ quản trị.','Out-of-scope data is hidden. Return or contact your administrator.','権限外の情報は非表示。戻るか管理者に連絡。')],stale:['clock',L('Thông tin đã cũ','Evidence is stale','情報が古くなっています'),L('Tạm ẩn chỉ dẫn dựa trên thông tin cũ. Xác minh lại vị trí và nguy cơ.','Guidance based on old evidence is hidden. Recheck position and hazards.','古い情報に基づく案内を非表示。位置と危険を再確認。')],blocked:['location',L('Không có tuyến được xác minh','No verified route','確認済み経路なし'),L('Không đoán hướng đi. Xác định mốc vị trí hoặc yêu cầu người hỗ trợ.','Do not guess a direction. Identify a landmark or request assistance.','向きを推測せず目印を確認するか支援を依頼。')]};let [ic,h,p]=cfg[state];return `<div class="state-view ${state}"><div class="state-icon">${icon(ic,53)}</div><h1>${h}</h1><p>${p}</p>${state==='loading'?'<div class="skeleton"></div><div class="skeleton"></div>':''}${['stale','blocked','offline'].includes(state)&&['Citizen','Responder'].includes(s.group)?fig('floor',{state,showRoute:false}):''}<div class="actions">${demoButton('retry',L('Xem trạng thái bình thường','Return to ready preview','通常のプレビューへ'),'check','secondary')}${s.group==='Citizen'&&state!=='denied'?button('C05',L('Mở phương án trợ giúp','Open assistance options','支援の選択肢'),'SOS'):''}</div></div>`;}
function getContent(s){if(state!=='ready')return stateContent(s);if(s.group==='Citizen')return phone(s);if(s.group==='Responder')return responder(s);if(s.group==='Command')return command(s);if(s.group==='Care profiles')return care(s);if(s.group==='Public address')return pa(s);if(s.group==='BMS integration')return SABMS.render(s,{lang,L,e,title,loc,icon,scene,fields,action});return `<div class="product-head"><h1>${e(title(s))}</h1></div>`+SAEnterprise.render(s,{lang,L,e,title,loc,icon,scene,fields,action});}
function renderNav(){const q=$('search').value.toLocaleLowerCase();let a=S.filter(s=>(s.id+' '+s.title+' '+title(s)+' '+s.role+' '+s.group).toLocaleLowerCase().includes(q));$('count').textContent=`${a.length} / ${S.length}`;let gs=[...new Set(a.map(s=>s.group))];$('nav').innerHTML=gs.map(g=>`<h3>${e(group(g))}</h3>${a.filter(s=>s.group===g).map(s=>`<button class="navitem ${s.id===current?'active':''}" data-go="${s.id}" ${s.id===current?'aria-current="page"':''}><b>${s.id}</b><span>${e(title(s))}</span></button>`).join('')}`).join('');}
function render(){const s=find(current)||find('C35');current=s.id;const mobile=forced??(['Citizen','Responder'].includes(s.group)||s.group==='Care profiles'&&!['H04','H07','H08','H09','H10','H11'].includes(s.id));document.documentElement.lang=lang;$('language').value=lang;$('state').innerHTML=Object.keys(labels).map(k=>`<option value="${k}" ${state===k?'selected':''}>${L(...labels[k])}</option>`).join('');$('search').placeholder=L('Tìm mã hoặc chức năng','Find an ID or function','ID・機能を検索');$('studioLabel').textContent=L('Bản thiết kế · không điều khiển hệ thống thật','Design prototype · no live operations','設計プロトタイプ・実システム操作なし');$('view').textContent=mobile?L('Xem rộng','Wide view','ワイド表示'):L('Điện thoại','Phone','スマホ表示');$('crumb').innerHTML=`<span class="screen-id">${s.id}</span><span>${e(group(s.group))}</span><strong>${e(title(s))}</strong><span class="spacer"></span>${badge(L('Thiết kế v2','Design v2','設計 v2'),'blue')}`;$('frame').className='frame'+(mobile?' mobile':'');$('frame').dataset.screen=s.id;$('frame').dataset.context=s.group;$('frame').dataset.state=state;
 $('frame').innerHTML=`<div class="appbar"><span class="brand"><span class="brand-mark">${icon('shield',20)}</span>SmartAlarm</span><span class="scope">Harbor Campus / EU</span><span class="sim">${L('Minh họa','Illustrative','参考')}</span></div><div class="product-body ${s.group==='Command'?'command-body':''}">${getContent(s)}</div>${mobile?`<nav class="phone-nav" aria-label="${L('Điều hướng ứng dụng','App navigation','アプリナビゲーション')}">${[['C01','shield',L('An toàn','Safety','安全')],['C05','SOS','SOS'],['C19','team',L('Người thân','Circles','家族')],['H01','person',L('Hồ sơ','Profile','情報')]].map(([id,ic,text])=>`<button data-go="${id}" class="${id===current?'selected':''}">${icon(ic,23)}${text}</button>`).join('')}</nav>`:''}`;
 $('specLabel').textContent=L('Thông tin dành cho người review thiết kế','Designer review information','設計レビュー情報');$('spec').innerHTML=`<section><h3>${e(s.role)} · FR-${s.id}</h3><p>${e(SMARTALARM.workflow[s.id])}</p><p>${e(SMARTALARM.rules[s.id][lang])}</p></section><section><h3>${L('Hành động gốc và điều hướng','Original action and navigation','元の操作と遷移')}</h3><p>${e(s.action)} → ${s.next}</p><a href="${lang==='en'?'English/':''}Screen-Specifications.html#${s.id.toLowerCase()}">${L('Mở đặc tả','Open specification','仕様を開く')}</a></section>${fields(s)}`;renderNav();}
function go(id){if(!find(id))return;if(current==='C06'){sosLocation=$('sosLocation')?.value||sosLocation;sosNote=$('sosNote')?.value||sosNote;}window.speechSynthesis?.cancel();if(id!==current)navHistory.push(current);current=id;state='ready';selection=id==='C05'?sosChoice:0;layer='hazard';confirmedPin=false;location.hash=id;render();window.scrollTo({top:0,behavior:'instant'});}
function toast(msg){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.role='status';el.textContent=msg;document.body.append(el);setTimeout(()=>el.remove(),4200);}
function modal(titleText,body){modalFocus=document.activeElement;document.querySelector('.dialog-backdrop')?.remove();const d=document.createElement('div');d.className='dialog-backdrop';d.innerHTML=`<section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialogTitle"><h2 id="dialogTitle">${e(titleText)}</h2><p>${e(body)}</p><div class="actions"><button class="secondary" data-demo="closeDialog">${L('Đóng','Close','閉じる')}</button></div></section>`;document.body.append(d);d.querySelector('button').focus();}
function playVoice(){if(current==='C27')return;const v=voiceLanguage||lang;const words={vi:'Đây là âm thanh minh họa, không dùng cho thoát hiểm thực tế. Trong sơ đồ mẫu, dùng biển cầu thang Tây làm mốc. Khi chưa xác định được vị trí, không đoán hướng đi và yêu cầu hỗ trợ.',en:'This is a design sample, not real evacuation guidance. In the sample, use the West stair sign as a landmark. If location is uncertain, do not guess a direction; request assistance.',ja:'これは設計用サンプルで、実際の避難には使用しないでください。参考図では西階段の標識を目印にします。現在地が不確かな場合は向きを推測せず支援を依頼してください。'};if(!window.speechSynthesis){modal(L('Âm thanh không khả dụng','Audio unavailable','音声は利用不可'),words[v]);return;}const withdrawn=['C37','C38'].includes(current)||state!=='ready';const uncertain=current==='C36';const safety={vi:'Âm thanh minh họa. Không có hướng đi đã xác minh. Không đoán phương hướng. Xác nhận mốc vị trí hoặc yêu cầu hỗ trợ.',en:'Design sample. No verified direction is available. Do not guess a heading. Confirm a landmark or request assistance.',ja:'設計用サンプルです。確認済みの方向はありません。方向を推測せず、目印を確認するか支援を依頼してください。'};const u=new SpeechSynthesisUtterance(withdrawn||uncertain?safety[v]:words[v]);u.lang={vi:'vi-VN',en:'en-US',ja:'ja-JP'}[v];speechSynthesis.cancel();speechSynthesis.speak(u);toast(L('Đang phát âm thanh mẫu theo yêu cầu','Playing sample audio on request','操作に応じてサンプル音声を再生'));}
function demo(key){if(key==='voice'){playVoice();return;}if(key==='stopVoice'){window.speechSynthesis?.cancel();return;}if(key==='retry'){state='ready';render();return;}if(key==='closeDialog'){document.querySelector('.dialog-backdrop')?.remove();modalFocus?.focus();return;}if(key==='plusPeople'||key==='minusPeople'){people=Math.max(1,Math.min(99,people+(key==='plusPeople'?1:-1)));$('people').textContent=people;return;}if(key==='confirmPin'){sosLocation=$('sosLocation')?.value||sosLocation;sosNote=$('sosNote')?.value||sosNote;confirmedPin=true;render();return;}if(key==='sendMessage'){const v=$('message')?.value.trim();if(!v)return;const el=document.createElement('div');el.className='bubble me';el.textContent=v;$('messages').append(el);$('message').value='';return;}if(key.startsWith('quick')){$('message').value=[L('Tôi đang ở phòng 505.','I am in Room 505.','505号室にいます。'),L('Tôi cần người hỗ trợ di chuyển.','I need mobility assistance.','移動支援が必要です。'),L('Tình trạng của tôi đã thay đổi.','My situation has changed.','状況が変わりました。')][+key.slice(-1)];$('message').focus();return;}if(key==='mic'){modal(L('Quyền microphone','Microphone permission','マイク権限'),L('Chưa yêu cầu quyền thiết bị. Sản phẩm thật cần kiểm tra vùng phát, quyền và tủ ưu tiên trước khi mở phiên.','No device permission has been requested. The product must validate zones, authority and local priority before a session.','端末権限は要求していません。実製品は放送範囲・権限・現地優先を確認します。'));return;}if(key==='declineTask'){modal(L('Báo không thể nhận nhiệm vụ','Decline assignment','任務を辞退'),L('Cần ghi lý do và để điều phối tìm đội khác. Bản mẫu không thay đổi phân công thật.','Record a reason so dispatch can find another team. This prototype changes no real assignment.','理由を記録し別チームへ。実際の割当は変更されません。'));return;}modal(L('Tương tác trong bản mẫu','Prototype interaction','プロトタイプ操作'),L('Thao tác được xem xét tại đây; không gửi thông tin hoặc lệnh ra ngoài.','Review this operation here; no information or command is sent externally.','ここで操作を確認します。外部送信や命令なし。'));}
document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.repeat){playVoice();return;}if(b.dataset.go){if(b.dataset.primary&&$('screenform')&&!$('screenform').reportValidity())return;go(b.dataset.go);return;}if(b.dataset.select!==undefined){selection=+b.dataset.select;if(current==='C05')sosChoice=selection;render();return;}if(b.dataset.layer){layer=b.dataset.layer;render();return;}if(b.dataset.voiceLang){voiceLanguage=b.dataset.voiceLang;render();return;}if(b.dataset.demo)demo(b.dataset.demo);});
document.addEventListener('keydown',ev=>{const d=document.querySelector('.dialog-backdrop');if(d&&ev.key==='Tab'){ev.preventDefault();d.querySelector('button').focus();}if(ev.key==='Escape'&&d){d.remove();modalFocus?.focus();}});
$('language').onchange=()=>{lang=$('language').value;window.speechSynthesis?.cancel();history.replaceState(null,'',location.pathname+'?lang='+lang+(query.has('focus')?'&focus=1':'')+'#'+current);render();};$('state').onchange=()=>{state=$('state').value;window.speechSynthesis?.cancel();render();};$('search').oninput=renderNav;$('view').onclick=()=>{forced=!$('frame').classList.contains('mobile');render();};$('prev').onclick=()=>go(S[(S.findIndex(s=>s.id===current)-1+S.length)%S.length].id);$('next').onclick=()=>go(S[(S.findIndex(s=>s.id===current)+1)%S.length].id);window.onhashchange=()=>{const id=location.hash.slice(1);if(id!==current&&find(id)){current=id;state='ready';render();}};if(query.has('focus'))document.body.classList.add('focus-mode');window.SAPrototype={go,render,getState:()=>({current,lang,state,layer}),setState:v=>{state=v;render();}};render();
})();
